"""Standalone, accessible sign-in and signup pages for the BluQQ workspace."""

# ruff: noqa: E501 - embedded HTML/CSS/JavaScript.


def auth_page(page="login", google_ready=False, email_ready=False, signup_mode="invite"):
    if page == "admin":
        html = auth_page("login", False, False, "disabled")
        start, end = html.index('<a class="google '), html.index('<div id="error"')
        html = html[:start] + html[end:]
        return (html.replace('Welcome back', 'Admin sign in')
                .replace('Sign in to your LinkedIn research workspace.', 'Use your existing administrator username and password for the shared dashboard.')
                .replace('<label for="email">Email address</label>', '<label for="email">Username</label>')
                .replace('name="email" type="email" autocomplete="email"', 'name="username" type="text" autocomplete="username"')
                .replace('placeholder="you@company.com"', 'placeholder="Admin username"')
                .replace("const page='login'", "const page='admin/login'")
                .replace('Access is provided by the app owner. Use your approved account to sign in.<br><a href="/linkedin-automation/admin">Admin login</a>', '<a href="/linkedin-automation/login">Back to Google / email login</a>')
                .replace('Access is limited to email addresses approved by the app owner. Your workspace login is separate from your LinkedIn connection.', 'Administrator access applies to the shared dashboard. Private Google workspaces remain separate.'))
    signup, verify = page == "signup", page == "verify"
    title = "Check your inbox" if verify else "Create your account" if signup else "Welcome back"
    subtitle = "Enter the 8-digit code sent to your approved email address." if verify else "Join your private LinkedIn research workspace." if signup else "Sign in to your LinkedIn research workspace."
    name = '<label for="name">Full name</label><input id="name" name="name" autocomplete="name" maxlength="100" required placeholder="Your name">' if signup else ""
    password = '' if verify else '<label for="password">Password</label><div class="password"><input id="password" name="password" type="password" autocomplete="'+('new-password' if signup else 'current-password')+'" minlength="'+('12' if signup else '1')+'" maxlength="128" required placeholder="'+('At least 12 characters' if signup else 'Enter your password')+'"><button id="showPassword" type="button" aria-label="Show password">Show</button></div>'
    code = '<label for="code">Verification code</label><input id="code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{8}" maxlength="8" required placeholder="8-digit code">' if verify else ''
    google = '' if verify else '<a class="google '+('disabled' if not google_ready else '')+'" '+('aria-disabled="true"' if not google_ready else 'href="/linkedin-automation/api/auth/google"')+'><span aria-hidden="true" class="g">G</span> Continue with Google</a>'+('' if google_ready else '<p class="availability">Google sign-in is not available yet. Contact the app owner.</p>')+'<div class="divider"><span>or use your email</span></div>'
    email_note = '<p class="availability">Email signup is currently unavailable. Use Google sign-in if available, or contact the app owner.</p>' if signup and not email_ready and signup_mode == "email" else ''
    if signup and signup_mode == "invite":
        name += '<label for="invite_code">One-time access code</label><input id="invite_code" name="invite_code" type="password" autocomplete="off" maxlength="128" required placeholder="Code provided by the app owner"><p class="availability">Ask the app owner for your access code. It is used once at signup; future sign-ins need only your email and password. No verification email is sent.</p>'
    signup_disabled = signup and signup_mode == "email" and not email_ready
    bottom = '<a href="/linkedin-automation/signup">Request a new verification code</a>' if verify else 'Already have an account? <a href="/linkedin-automation/login">Sign in</a>' if signup else 'New to BluQQ? <a href="/linkedin-automation/signup">Create an account</a>'
    if signup_mode == "disabled":
        bottom = 'Access is provided by the app owner. Use your approved account to sign in.'
    if page == "login":
        bottom += '<br><a href="/linkedin-automation/admin">Admin login</a>'
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'''+title+''' · BluQQ</title>
<style>
:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#17283e;background:#f6f8fc;font-synthesis:none}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;grid-template-columns:minmax(320px,44%) 1fr}a{color:#2557df;text-decoration:none}a:hover{text-decoration:underline}aside{background:#101d33;color:#fff;padding:48px 11%;display:flex;flex-direction:column;justify-content:space-between;position:relative;overflow:hidden}aside:after{content:"";position:absolute;width:480px;height:480px;border:1px solid #294368;border-radius:50%;right:-300px;bottom:-230px;box-shadow:0 0 0 70px #ffffff03,0 0 0 140px #ffffff02;pointer-events:none}.brand{display:flex;align-items:center;gap:12px;font-weight:750;font-size:23px;letter-spacing:-.6px}.mark{width:43px;height:43px;border-radius:12px;background:#2d64ef;color:#fff;display:grid;place-items:center;font-size:17px;letter-spacing:-1px}.label{font-size:11px;letter-spacing:2px;color:#9db9e1;font-weight:650;text-transform:uppercase;margin-bottom:23px}aside h1{font-size:clamp(32px,3.3vw,50px);line-height:1.15;letter-spacing:-1.9px;margin:0 0 24px;max-width:430px}aside p{font-size:15px;line-height:1.8;color:#afbed3;max-width:370px}.features{display:grid;gap:18px;margin-top:38px;font-size:14px;color:#e0e8f4}.features span{display:flex;gap:12px;align-items:center}.dot{width:7px;height:7px;background:#65ceb5;border-radius:50%;flex:none}aside footer{font-size:12px;color:#889cb8;margin-top:40px}.content{display:flex;align-items:center;justify-content:center;padding:50px 28px}.card{max-width:420px;width:100%}.badge{display:inline-flex;align-items:center;gap:8px;background:#eaf0ff;color:#2757c8;padding:7px 11px;border-radius:7px;font-size:11px;font-weight:650;margin-bottom:26px}.badge:before{content:"";width:6px;height:6px;border-radius:50%;background:#3d6ae0}h2{font-size:32px;line-height:1.2;letter-spacing:-1px;margin:0 0 12px}.subtitle{font-size:14px;color:#6c7c92;line-height:1.7;margin:0 0 28px}.google{width:100%;height:48px;border:1px solid #d8dfeb;border-radius:9px;background:white;color:#23344a;display:flex;align-items:center;justify-content:center;gap:12px;font-size:14px;font-weight:600}.google:hover{background:#f0f4fb;text-decoration:none}.g{font-size:20px;color:#4285f4;font-weight:750}.disabled{opacity:.5;cursor:not-allowed}.divider{display:flex;align-items:center;gap:15px;margin:25px 0;color:#8793a6;font-size:11px}.divider:before,.divider:after{content:"";height:1px;background:#e0e6ef;flex:1}label{display:block;font-size:12px;font-weight:650;margin:18px 0 8px}input{width:100%;height:48px;background:white;border:1px solid #d8dfeb;border-radius:8px;padding:0 14px;font:inherit;font-size:14px;color:#17283e}input::placeholder{color:#95a0b1}input:focus{outline:3px solid #dae5ff;border-color:#4778e9}.password{position:relative}.password input{padding-right:66px}.password button{position:absolute;right:8px;top:8px;height:32px;background:transparent;border:0;color:#657893;cursor:pointer;font-size:11px;font-weight:650}button.primary{width:100%;border:0;border-radius:8px;background:#285ce8;color:white;height:48px;margin-top:24px;cursor:pointer;font:inherit;font-size:14px;font-weight:650}button.primary:hover{background:#1d4fd2}button:disabled{opacity:.6;cursor:wait}.error{padding:12px 14px;margin:18px 0;background:#fff0f0;border:1px solid #f3cdcd;border-radius:8px;color:#9d2a2a;font-size:13px;line-height:1.6}.error[hidden]{display:none}.availability{font-size:12px;color:#6d7c92;line-height:1.6;margin:12px 0}.bottom{text-align:center;color:#748299;font-size:13px;margin-top:25px}.bottom a{font-weight:650}.restriction{border-top:1px solid #e0e6ef;margin-top:32px;padding-top:20px;color:#8490a1;font-size:11px;line-height:1.7}a:focus-visible,button:focus-visible{outline:3px solid #adc5ff;outline-offset:3px}@media(max-width:800px){body{grid-template-columns:1fr}aside{padding:24px 28px}aside .intro,aside footer{display:none}.content{padding:38px 24px}.badge{margin-bottom:22px}}@media(prefers-reduced-motion:no-preference){button,a,input{transition:background .15s,border-color .15s}}
</style></head><body>
<aside><div class="brand"><span class="mark">BQ</span>BluQQ</div><div class="intro"><div class="label">Your research workspace</div><h1>Find the right people.<br>Build better connections.</h1><p>Bring your LinkedIn research, lead qualification and reviewed outreach into one focused workspace.</p><div class="features"><span><i class="dot"></i> Campaigns built around your audience</span><span><i class="dot"></i> A private workspace for your leads</span><span><i class="dot"></i> Outreach you review and control</span></div></div><footer>BluQQ · LinkedIn Automation</footer></aside>
<main class="content"><section class="card" aria-labelledby="title"><div class="badge">APPROVED ACCESS ONLY</div><h2 id="title">'''+title+'''</h2><p class="subtitle">'''+subtitle+'''</p>'''+google+'''<div id="error" class="error" role="alert" hidden></div><form id="authForm">'''+name+'''<label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" maxlength="254" required placeholder="you@company.com">'''+password+code+email_note+'''<button class="primary" id="submit" type="submit" '''+('disabled' if signup_disabled else '')+'''>'''+('Verify email & continue' if verify else 'Create account' if signup else 'Sign in')+'''</button></form><p class="bottom">'''+bottom+'''</p><p class="restriction">Access is limited to email addresses approved by the app owner. Your workspace login is separate from your LinkedIn connection.</p></section></main>
<script>
const page='''+repr(page)+''', form=document.getElementById('authForm'),error=document.getElementById('error'),submit=document.getElementById('submit');
const problem=message=>{error.textContent=message;error.hidden=false};
const failure=new URLSearchParams(location.search).get('error');if(failure)problem(failure==='access'?'This email has not been granted access. Contact the app owner.':'Google sign-in was not completed. Please try again.');
if(page==='verify')document.getElementById('email').value=sessionStorage.getItem('bluqqSignupEmail')||'';
document.getElementById('showPassword')?.addEventListener('click',e=>{const input=document.getElementById('password'),show=input.type==='password';input.type=show?'text':'password';e.target.textContent=show?'Hide':'Show';e.target.setAttribute('aria-label',show?'Hide password':'Show password')});
form.onsubmit=async event=>{event.preventDefault();error.hidden=true;const label=submit.textContent;submit.disabled=true;submit.textContent='Please wait…';try{const payload=Object.fromEntries(new FormData(form));const r=await fetch('/linkedin-automation/api/auth/'+page,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await r.json();if(!r.ok)throw Error(data.detail||'Could not complete the request');if(page==='signup'&&!data.next){sessionStorage.setItem('bluqqSignupEmail',payload.email);location.assign('/linkedin-automation/verify')}else{sessionStorage.removeItem('bluqqSignupEmail');location.assign(data.next||'/linkedin-automation/')}}catch(e){problem(e.message)}finally{submit.disabled=false;submit.textContent=label}};
</script></body></html>'''


ACCOUNT_PANEL = '''<section class="panel" style="padding:14px 20px;margin-bottom:16px;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap"><div><strong>Private workspace</strong><div class="sub" id="signedInEmail">Loading account…</div></div><button class="btn" id="signOutAccount" type="button">Sign out</button></section>'''
ACCOUNT_SCRIPT = '''<script>document.addEventListener('DOMContentLoaded',()=>{fetch('/api/auth/me').then(r=>r.json()).then(v=>{document.getElementById('signedInEmail').textContent=v.email||'Session expired'}).catch(()=>{});document.getElementById('signOutAccount').onclick=async()=>{const r=await fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(r.ok)location.assign('/linkedin-automation/login');else notice('Could not sign out. Please try again.')}});</script>'''

ADMIN_PANEL = ACCOUNT_PANEL.replace('Private workspace', 'Administrator · Shared workspace').replace('Loading account…', 'Admin access · Use Google login for searches on your own computer.')
ADMIN_PANEL = ADMIN_PANEL.replace('</div><button', '<p class="sub">For LinkedIn searches on this PC, <a href="/linkedin-automation/login">sign in with your approved Google account</a>.</p></div><button', 1)
ADMIN_SCRIPT = ACCOUNT_SCRIPT.replace("v.email||'Session expired'", "v.role==='admin'?'Signed in as '+v.username:v.email||'Session expired'")
ADMIN_PANEL = ADMIN_PANEL.replace('<button class="btn" id="signOutAccount"', '<a class="btn" href="/linkedin-automation/admin/controls">Admin controls</a><button class="btn" id="signOutAccount"')
ADMIN_PANEL = ADMIN_PANEL.replace('For LinkedIn searches on this PC, <a href="/linkedin-automation/login">sign in with your approved Google account</a>.', 'For shared admin searches, <a href="/linkedin-automation/connect-computer">connect this computer</a>.')
